from scripts.cloud_walkforward_study import ROOT,DOCS,ASSETS,METHODS,RISKS,read,freeze

PUBLIC=ROOT/'docs/verification/eth-cloud-two-year-20260910'

HTML=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>四个标的 · 周期选择与利润保护</title>
<style>:root{font-family:system-ui,"Microsoft YaHei",sans-serif;color:#24344a;background:#f4f6fa}*{box-sizing:border-box}body{margin:0}main{max-width:1450px;padding:28px 24px 60px;margin:auto}h1{font-size:29px}h2{font-size:22px}h3{font-size:17px}p{line-height:1.9}.box{background:white;border:1px solid #e0e5ed;border-radius:12px;padding:23px;margin:24px 0}.lead{border-left:4px solid #4078b6;background:#ebf2fc;padding:16px 23px}.muted{color:#65758c;font-size:14px}.controls{display:flex;flex-wrap:wrap;gap:20px;align-items:center;margin:18px 0}select{font:inherit;padding:8px;border:1px solid #becadb;border-radius:6px;max-width:100%}a{color:#2d69a8}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:14px}th,td{text-align:right;padding:11px;border-bottom:1px solid #e2e7ef}th{font-weight:500;background:#f5f7fb}td:first-child,th:first-child{text-align:left}.pos{color:#087e63}.neg{color:#bb4355}.selected{background:#eaf2fd}svg{width:100%;height:auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.pill{font-size:13px;border-radius:4px;background:#e8eef8;padding:3px 6px}@media(max-width:800px){main{padding:18px 12px}.box{padding:15px}.grid{grid-template-columns:1fr}h1{font-size:25px}}</style>
<main><a href="cloud-timeframes.html">← 原策略周期比较</a><p class="muted">PAXG · ZEC · ETH · BTC ｜ 原EMA通道策略 ｜ 先用过去选择，再计算后续表现</p><h1>怎么选周期和参数？利润应该怎样保护？</h1>
<div class="lead"><p id="lead"></p><p>本轮先固定选择办法，再运行四个标的。比较回吐50%、35%、25%，以及增加价格回撤5%／10%上限；另配对比较ATR止损和反向等两根收盘确认。没有根据后面的结果更换挑选标准。</p></div>
<section class="box"><h2>先看：过去选出来的版本，后来赚了吗？</h2><div class="controls"><label>可选择的周期 <select id="pool"><option value="intraday">5分钟、15分钟、30分钟、1小时：6段检验</option><option value="all5">再加日线：2段检验</option></select></label></div><p id="period"></p><div id="mainTable" class="scroll"></div><p class="muted">“按附近参数稳定性选”同时选择周期、EMA、突破门槛、百分比初始止损和利润保护。“只挑过去收益最高”是同一候选范围的对照，也只使用当时之前的数据。若过去没有合格版本，就保持空仓；空仓不是策略赚到的钱。每个标的各自从10,000开始全本金复投，未组成组合，不计手续费和滑点，不加杠杆。</p></section>
<section class="box"><h2>利润保护：保持同一套入场参数，哪种退出更好？</h2><div class="controls"><label>入场设置 <select id="basis"><option value="fixed">固定原ETH小时参数，不更换</option><option value="paired">每半年按原50%版本过去表现选定</option></select></label></div><p id="basisNote"></p><div id="protectionTable" class="scroll"></div><p>50%是允许退还最高利润的一半；增加价格回撤上限则另设一道出口。例如100买入、最高涨到200：原50%保护价为150；5%价格回撤上限为190，10%上限为180。哪条保护线更近，就使用哪条。所有版本都保留反向信号退出。</p><p class="muted">表中按同一段历史比较，不能把事后收益最高的一种说成已经事先选中。退出改变后，持仓状态和后续实际入场也会变化，不能直接从旧交易里减掉回吐金额当成新收益。</p></section>
<section class="box"><h2>ATR止损＋反向等两根：分开看才知道是哪一步有帮助</h2><div class="controls"><label>标的 <select id="asset"><option value="paxg">PAXG</option><option value="zec">ZEC</option><option value="eth">ETH</option><option value="btc">BTC</option></select></label></div><p>下面继续使用上一节选定的“入场设置”。每一行只指定初始止损和反向确认方式，每一列指定利润保护。2倍／3倍ATR使用ATR14，在信号收盘时确定距离，以实际入场价设置初始止损；它替代百分比止损。等待第二根收盘时，原有止损与利润保护仍然有效。</p><div id="riskMatrix" class="scroll"></div><p class="muted">这些ATR组合都是本轮开始前固定的对照，没有拿它们的后续收益来倒选参数。两根确认只延后持仓的反向退出／切换，不会把每一次空仓入场也统一延后两根。</p><h3>选一组看交易情况</h3><div class="controls"><label>止损与确认 <select id="risk"></select></label><label>利润保护 <select id="method"></select></label></div><div id="riskDetail" class="scroll"></div><div id="riskStages" class="scroll"></div></section>
<section class="box"><h2>每半年的选择记录：具体选了什么，后来表现怎样</h2><div class="controls"><label>查看选择办法 <select id="policy"><option value="joint">按附近参数稳定性选，包括利润保护</option><option value="return_leader">只挑过去三年收益最高</option><option value="method_g50">按稳定性选，保护固定回吐50%</option><option value="method_g35">按稳定性选，保护固定回吐35%</option><option value="method_g25">按稳定性选，保护固定回吐25%</option><option value="method_g50c5">按稳定性选，回吐50%＋价格回撤5%</option><option value="method_g50c10">按稳定性选，回吐50%＋价格回撤10%</option></select></label></div><div id="ledger" class="scroll"></div><div id="equityChart"></div><p class="muted">蓝线为所选办法，灰线为固定原ETH小时参数＋50%保护。初始1倍。所有办法在预先固定的半年边界清仓并重新开始，盈亏计入下一段本金；同样的边界处理用于所有对照。最后一段截至2026年9月10日，不足半年。</p><h3>逐年收益与交易统计</h3><div id="yearTable" class="scroll"></div><div id="policyStats" class="scroll"></div></section>
<section class="box"><h2>这次怎样减少“只对历史有效”的风险</h2><p>每次只取此前三年，把它分成六个半年。对每套设置，先看这六段通常表现怎样；再看仅改一个参数的附近四套设置是否也能工作。按这五套设置的典型表现排序，不用最好一笔或某一年的暴涨决定胜负。自身三年需盈利且至少有30笔已平仓交易；附近参数的典型表现也需为正，否则该段空仓。这套规则在新结果出来前固定。</p><p>候选为EMA34／55／89、突破门槛0.4／0.8倍、初始止损1%／2%，共12套。宽度EMA31、不追超过2倍宽度、浮盈2%启动保护固定。每个周期与五种保护相配，每币300套，四币共1,200套基础候选。ATR与双收盘确认是额外固定配对对照，没有事后追加范围。</p><p>日内周期从2020年10月起具备共同历史，用前三年选择，2023年10月起逐段检验。日线因为PAXG上市和650根预热限制，共同起点为2022年10月，必须到2025年10月才能完成三年选择，因此只有最后两段可比。这两个范围的累计收益不能直接排名。</p><p>这仍然是已看过历史上的回顾性检验。我们的规则设计已受此前研究影响，四个标的也并不相互独立，所以结果只能支持或削弱信心，不能证明排除了过拟合。日线仅两段，尤其不能据此认定某周期长期最优。把规则冻结后，在新行情上持续记录，才会增加新的证据。</p><p class="muted" id="verification"></p><p class="muted">行情取自项目MarketDataService／KlineStore的Binance原生现货K线；多空均为价格模拟。缺根保持缺口。信号收盘确认，下一根实际开盘成交；保护线在收盘后更新，下一根开始生效，不利用本根的最高价倒推本根先前退出。大周期看不到精确盘内路径；各周期回撤按该周期收盘权益计算。所有原版源码、参数、结果及本轮记录均保留。</p></section></main>
<script>(()=>{const D=__DATA__,A=['paxg','zec','eth','btc'],M=D.plan.methods,R=D.plan.risks,$=id=>document.getElementById(id),nm=x=>x==null?'—':x.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}),pct=x=>x==null?'—':(x>=0?'+':'')+nm(x)+'%',pc=x=>x==null?'—':`<span class="${x>=0?'pos':'neg'}">${pct(x)}</span>`,tf={'5m':'5分钟','15m':'15分钟','30m':'半小时','1h':'1小时','1d':'日线'},tbl=(h,rows)=>'<table><thead><tr>'+h.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>',riskPolicy=(b,m,r)=>b+'_'+m+(r==='r0'?'':'_'+r);
$('method').innerHTML=Object.entries(M).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('');$('risk').innerHTML=Object.entries(R).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('');
$('verification').textContent=`已核对${D.verification.candidate_traces}份基础候选记录、${D.verification.unique_replays}份实际后续分段重放、${D.verification.policy_traces}份累计结果。选择记录从仅含此前表现的输入重新计算一致；逐笔复利与账户终值一致。关闭新增价格回撤上限时，新引擎副本与原引擎的全部记录一致。原引擎没有修改。`;
function detailName(id){if(!id)return['空仓','—','—','—','—'];let [t,k,m,r]=id.split('__'),p=D.plan.variants[k];return[tf[t],`EMA${p.center_length}；宽度${p.width_length}`,p.trigger_mult+'倍',R[r].atr_stop_mult?R[r].atr_stop_mult+'×ATR14':p.initial_stop_pct+'%',M[m].label]}
function metricsTable(x){let m=x.metrics;return tbl(['累计收益','交易数','赚钱','亏钱','胜率','平均赚一笔','平均亏一笔','典型持仓','最大回撤'],[[pc(m.return_pct),m.trades,m.wins,m.losses,nm(m.win_rate)+'%',pc(m.mean_win_pct),pc(m.mean_loss_pct),nm(m.median_hours)+'小时',nm(m.max_drawdown_pct)+'%']])}
function draw(){let pool=$('pool').value,a=$('asset').value,basis=$('basis').value,policy=$('policy').value;const get=(a,k)=>D.results[a][pool][k],one=get(a,policy),ref=get(a,'fixed_g50');
$('period').textContent=pool==='intraday'?'后续检验：2023年10月1日—2026年9月10日，6段。每次只用之前三年，选择5分钟、15分钟、30分钟或1小时。':'后续检验：2025年10月1日—2026年9月10日，2段。每次只用之前三年，五个周期都可选，包含日线。';
$('lead').innerHTML=A.map(a=>{let m=get(a,'joint').metrics;return `<b>${a.toUpperCase()}</b>：事先规定的选择办法，后续累计 ${pc(m.return_pct)}，${m.positive_segments}段赚、${m.negative_segments}段亏、${m.cash_segments}段空仓。`}).join('<br>');
$('mainTable').innerHTML=tbl(['标的','按附近参数稳定性选','只挑过去收益最高','固定原ETH小时参数','稳定性选：交易数','赚钱','亏钱','空仓段数'],A.map(a=>{let m=get(a,'joint').metrics;return[a.toUpperCase(),pc(m.return_pct),pc(get(a,'return_leader').metrics.return_pct),pc(get(a,'fixed_g50').metrics.return_pct),m.trades,m.wins,m.losses,m.cash_segments]}));
$('basisNote').textContent=basis==='fixed'?'四个标的都固定1小时、EMA55、宽度31、突破0.4倍、不追2倍，原初始止损1%。这里只改变退出方式，作为完整的配对对照。':'每个标的每半年都先用过去数据，在原50%保护下选出周期和入场设置；五种保护沿用该设置。原版选择空仓的段，五种也都空仓。';
$('protectionTable').innerHTML=tbl(['利润保护方式',...A.map(a=>a.toUpperCase())],Object.entries(M).map(([k,v])=>[v.label,...A.map(a=>pc(get(a,riskPolicy(basis,k,'r0')).metrics.return_pct))]));
$('riskMatrix').innerHTML=tbl(['初始止损与反向确认',...Object.values(M).map(x=>x.label)],Object.entries(R).map(([r,v])=>[v.label,...Object.keys(M).map(m=>pc(get(a,riskPolicy(basis,m,r)).metrics.return_pct))]));
let selected=get(a,riskPolicy(basis,$('method').value,$('risk').value));$('riskDetail').innerHTML=metricsTable(selected);$('riskStages').innerHTML=tbl(['后续期间','该段收益','交易数','当时的周期','中心均线','初始止损'],selected.stages.map(s=>[s.start.slice(0,10)+' → '+s.end.slice(0,10),pc(s.return_pct),s.trades,detailName(s.chosen)[0],detailName(s.chosen)[1],detailName(s.chosen)[3]]));
$('ledger').innerHTML=tbl(['后续期间','所选周期','中心与宽度','突破门槛','初始止损','利润保护','此前三年收益','后续这一段收益','后续笔数'],one.stages.map(s=>[s.start.slice(0,10)+' → '+s.end.slice(0,10),...detailName(s.chosen),pc(s.training_return_pct),pc(s.return_pct),s.trades]));
$('yearTable').innerHTML=tbl(['年份（首尾可能不足全年）','所选办法','固定原ETH小时参数'],one.years.map(y=>[y.label,pc(y.return_pct),pc(ref.years.find(x=>x.label===y.label)?.return_pct)]));$('policyStats').innerHTML=metricsTable(one);
let xs=one.curve||[],ys=ref.curve||[],all=[...xs,...ys],x0=all[0].timestamp,x1=xs[xs.length-1].timestamp,lo=Math.min(0,...all.map(x=>Math.log10(x.equity/10000))),hi=Math.max(.1,...all.map(x=>Math.log10(x.equity/10000))),xx=t=>75+(t-x0)/(x1-x0)*1000,yy=v=>245-(Math.log10(v/10000)-lo)/(hi-lo)*220,path=curve=>curve.map((v,i)=>(i?'L':'M')+xx(v.timestamp).toFixed(2)+' '+yy(v.equity).toFixed(2)).join(' ');let grid='';for(let v of [.001,.01,.1,.25,.5,1,2,5,10,50,100,1000]){if(Math.log10(v)<lo||Math.log10(v)>hi)continue;let y=yy(v*10000);grid+=`<path d="M75 ${y}H1075" stroke="#e4e9ef"/><text x="65" y="${y+4}" text-anchor="end" font-size="12">${v}倍</text>`}$('equityChart').innerHTML=`<svg viewBox="0 0 1100 285" role="img" aria-label="账户增长比较">${grid}<path d="${path(ys)}" fill="none" stroke="#a8b3c1" stroke-width="2"/><path d="${path(xs)}" fill="none" stroke="#397fc0" stroke-width="2.5"/><text x="75" y="276" font-size="12">${new Date(x0).toISOString().slice(0,10)}</text><text x="970" y="276" font-size="12">${new Date(x1).toISOString().slice(0,10)}</text></svg>`;
}
for(let id of ['pool','asset','basis','policy','risk','method'])$(id).addEventListener('change',draw);draw();})();</script></html>'''


def main():
    result=read(DOCS/'results.json');v=read(DOCS/'verification.json')
    assert result['status']=='completed' and v['status']=='passed'
    payload=deepcopy(result);payload['verification']={k:x for k,x in v.items() if k!='manifest'}
    for rs in payload['results'].values():
        for pool in rs.values():
            for k,item in pool.items():
                if k not in ('joint','return_leader','fixed_g50') and not k.startswith('method_'):item.pop('curve',None)
    html=HTML.replace('__DATA__',json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</','<\\/'))
    (DOCS/'cloud-walkforward.html').write_text(html,encoding='utf-8')
    (PUBLIC/'cloud-walkforward.html').write_text(html,encoding='utf-8')
    freeze(DOCS/'report-data.json',payload)
    print('REPORT http://127.0.0.1:8787/cloud-walkforward.html')


if __name__=='__main__':main()
